import numpy as np, json
def f(g):
    g=[r[:] for r in g]; H,W=len(g),len(g[0])
    cnt={}
    for r in range(H):
        for c in range(W):
            v=g[r][c]; cnt[v]=cnt.get(v,0)+1
    bg=max(cnt,key=cnt.get)
    others={k:v for k,v in cnt.items() if k!=bg}
    noise_col=None
    # noise = rarest color(s) that appear as single cells scattered
    best=min(others,key=lambda k:(others[k], -sum(1 for r in range(H) for c in range(W) if g[r][c]!=k)))
    noise_color=best
    out=[r[:] for r in g]
    for c in range(W):
        nrs=[r for r in range(H) if out[r][c]==noise_color]
        if nrs:
            nr=nrs[-1]
            for r in range(1,nr):
                if out[r][c]==bg: out[r][c]=noise_color
            out[nr][c]=4
    return out
